code='''def transform(grid):
    """Color background cells trapped between non-background cells on a row or column."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    marked = set()
    # For each line, color each contiguous background run with a non-background
    # cell on both sides. Non-background cells act as barriers.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != background:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == background:
                c += 1
            if start > 0 and c < w:
                for cc in range(start, c):
                    marked.add((r, cc))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != background:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == background:
                r += 1
            if start > 0 and r < h:
                for rr in range(start, r):
                    marked.add((rr, c))
    for r, c in marked:
        out[r][c] = 3
    return out
'''
